Func<Vector3,float> L=p=>alongX?p.x:p.z;Func<Vector3,float> C=p=>alongX?p.z:p.x;float top=Get<float>(site,"y");
var f=modules[index].GetComponentsInChildren<MeshFilter>().Single(v=>v.name=="Concrete walls roof and curbs");var old=f.sharedMesh;var mesh=UnityEngine.Object.Instantiate(old);mesh.name="Underpass "+(index+1)+" Painted Concrete";var vertices=mesh.vertices;var normals=mesh.normals;var art=new List<Vector4>();var fit=new List<Vector2>();
for(int v=0;v<vertices.Length;v++){
var p=f.transform.TransformPoint(vertices[v]);var n=f.transform.TransformDirection(normals[v]);float l=L(p);int k=1;while(k<left.Length-1&&L(left[k])<l)k++;float t=Mathf.InverseLerp(L(left[k-1]),L(left[k]),l);var a=Vector3.Lerp(left[k-1],left[k],t);var b=Vector3.Lerp(right[k-1],right[k],t);bool nearLeft=Mathf.Abs(C(p)-C(a))<.055f,nearRight=Mathf.Abs(C(p)-C(b))<.055f;bool inward=nearLeft?(alongX?n.z>.98f:n.x>.98f):nearRight?(alongX?n.z<-.98f:n.x<-.98f):false;float floor=nearLeft?a.y:b.y;float height=top-floor;float mask=inward?Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.2f,2.4f,height)):0;float u=(l-start)/12;bool covered=l>=Get<float>(site,"gapA")-.01f&&l<=Get<float>(site,"gapB")+.01f;float wallTop=float.MinValue;for(int j=0;j<4;j++)wallTop=Mathf.Max(wallTop,f.transform.TransformPoint(vertices[(v/4)*4+j]).y);float artHeight=Mathf.Clamp(wallTop-floor-.85f,.2f,3.6f);float y=p.y-floor-.40f;fit.Add(new Vector2(artHeight,0));art.Add(new Vector4((index==1?!nearRight:nearRight)?-u+100:u,y,mask,index*5+(nearRight?7:0)));
}
mesh.SetUVs(2,art);mesh.SetUVs(3,fit);if(mesh.vertexCount!=old.vertexCount||!mesh.triangles.SequenceEqual(old.triangles)||!mesh.vertices.SequenceEqual(old.vertices))throw new Exception("Geometry changed");
string path=Dir+"/Underpass "+(index+1)+" Painted Concrete.asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(saved);}else{saved=mesh;AssetDatabase.CreateAsset(saved,path);}saved.SetUVs(2,art);saved.SetUVs(3,fit);saved.UploadMeshData(false);EditorUtility.SetDirty(saved);f.sharedMesh=saved;f.GetComponent<MeshRenderer>().sharedMaterial=mat;PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<MeshRenderer>());geometries.Add(Tuple.Create(f,saved));walls+=2;log.AppendLine("Underpass "+(index+1)+": both inner retaining walls; atlas="+AssetDatabase.GetAssetPath(atlas)+"; unchanged vertices/triangles; full-height fit, top clearance=0.45m; painted wall vertices="+art.Count(v=>v.z>.01f));
}
var prefab=PrefabUtility.LoadPrefabContents(Prefab);try{foreach(var v in geometries){var module=v.Item1.transform.parent.name;var target=prefab.GetComponentsInChildren<Transform>(true).Single(t=>t.name==module).GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Concrete walls roof and curbs");target.sharedMesh=v.Item2;target.GetComponent<MeshRenderer>().sharedMaterial=mat;}PrefabUtility.SaveAsPrefabAsset(prefab,Prefab,out bool ok);if(!ok)throw new Exception("Road prefab save failed");}finally{PrefabUtility.UnloadPrefabContents(prefab);}
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");
var controller=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=controller.IsNight;
try{controller.ApplyDay();for(int index=0;index<2;index++){var site=typeof(FinalSunkenUnderpasses).GetMethod("InstalledSite",F).Invoke(null,new object[]{root,index});bool x=Get<bool>(site,"x");float center=Get<float>(site,"center"),side=Get<float>(site,"side");var road=modules[index].GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Continuous underpass roadway");var d=typeof(FinalSunkenUnderpasses).GetMethod("Read",F).Invoke(null,new object[]{road});float l=Get<float>(site,"gapA")-45;var p=x?new Vector3(l,0,side):new Vector3(side,0,l);object[] a={d,p,0f};if(!(bool)typeof(FinalSunkenUnderpasses).GetMethod("Height",F).Invoke(null,a))throw new Exception("Preview floor missing");p.y=(float)a[2]+2.2f;var target=p+(x?Vector3.right:Vector3.forward)*38;target.y+=.5f;typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,p,target,"Underpass-Wall-Art-"+(index+1)});}}
finally{if(night)controller.ApplyNight();else controller.ApplyDay();}
EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);log.AppendLine("SUCCESS: 2 underpasses / 4 walls; 14 existing atlas artworks; matte paint and concrete grain with worn blended edges; 0 extra renderers/triangles/lights/colliders/textures; 1 shared wall material; scene and road prefab saved; shader errors=0; backup="+backup);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/UnderpassWallArtReport.txt",log.ToString());}
